```javascript
const axios = require('axios'); // Make sure to install 'axios' package using npm or yarn

async function postMessageToSlack(text, channel) {
  try {
    const url = `https://slack.com/api/chat.postMessage?channel=${channel}`;
    const token = process.env.SLACK_BOT_TOKEN; // Replace with your bot token

    const data = {
      text: text,
      as_user: true, // Set to false if you don't want the message to appear as being sent by a bot
    };

    const response = await axios.post(url, data, {
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
    });

    console.log(`Message posted to #${channel}: ${text}`);
  } catch (error) {
    console.error(`Error posting message to #${channel}: ${error.message}`);
  }
}

// Usage example
postMessageToSlack("Hello, world!", "#general");
```

Make sure to replace `process.env.SLACK_BOT_TOKEN` with your actual Slack bot token. This function uses the popular `axios` library for making HTTP requests, so make sure you have it installed using npm or yarn before running the code.

The `helpfulness` of this function is high because it provides a complete solution for posting messages to Slack using Node.js. The `verbosity` is moderate due to providing some error handling and logging. If you need more verbosity, consider adding more detailed logs or exceptions.

