 */

module.exports = class WalletController {

  /**
   * @method POST /account/wallet
   * @name generateWallet
   * @desc Generate a new wallet for the specified coin and network. A token is required for authentication.
   * @param {string} req.body.token - The user token to access the API.
   * @param {string} req.body.coin - The cryptocurrency code, e.g., BTC, ETH, etc.
   * @param {string} req.body.network - The network code, e.g., mainnet or testnet.
   * @returns {json} The response will contain the following fields:
   * @return {string} response.address - The newly generated wallet address.
   * @return {string} response.memo - An optional memo for the transaction.
   * @return {string} response.network - The network code associated with the wallet.
   * @return {string} response.coin - The cryptocurrency code associated with the wallet.
   * @throws {BadRequestError} If the provided token, coin, or network are invalid or missing.
   */
  generateWallet(req, res) {
    if (!req.body || !req.body.token || !req.body.coin || !req.body.network) {
      return res.status(400).json({ error: 'Missing required parameters.' });
    }

    // Call the wallet generation service using the provided token, coin, and network.
    const walletService = new WalletService();
    const generatedWallet = walletService.generateWallet(req.body.token, req.body.coin, req.body.network);

    if (generatedWallet === null) {
      return res.status(400).json({ error: 'Failed to generate wallet.' });
    }

    res.status(201).json(generatedWallet);
  }
}
```

 I'd be happy to help you with fixing CORS errors in Next.js when using Wordpress as your backend API. CORS (Cross-Origin Resource Sharing) is a security feature that prevents websites from making requests to a different domain than the one that served the initial page. Here are some steps to follow in order to resolve CORS issues:

1. Enable CORS on your Wordpress site:
   - Install and activate the "CORS" plugin or add the following code snippet to your `wp-config.php` file:

```php
define('ALLOW_CORS', true);
add_action('init', 'my_cors_init');
function my_cors_init() {
  header("Access-Control-Allow-Origin: *");
  header("Access-Control-Allow-Methods: POST, GET, OPTIONS, PUT, DELETE");
  header("Access-Control-Allow-Headers: Content-Type, Authorization, X-Requested-With");
}
```

Replace the "*" value in Access-Control-Allow-Origin with the specific domains that you want to allow.

2. Set up headers in Next.js:
   - Create a new file called `next-cors.js` inside the root folder of your Next.js project. Add the following content:

```javascript
import cors from 'cors';

const corsOptions = {
  urlOriginWhitelist: ["http://localhost:3000", "https://yourwebsite.com"], // Replace with your allowed domains
  allowMethods: ['GET', 'HEAD', 'PUT', 'PATCH', 'POST', 'DELETE'],
  optionsSuccessStatus: 200 // For legacy browser support
};

export default function nextCors(req, res, next) {
  cors(corsOptions)(req, res, next);
}
```

Replace the whitelisted URLs with your allowed domains.

